uint32_t BsimsoiGenModel::numInternalNodes() const {
    // BSIMSOI 动态节点数
    // rdsMod=0: di/si 折叠到 d/s（省 2 节点）
    // rgateMod=0: gi/gm 折叠到 g（省 2 节点）
    // rbodyMod=0: sb/db/b 折叠（省 3 节点）
    // shmod=0: t 折叠到 e（省 1 节点）
    // p (substrate contact): 总是需要
    uint32_t count = 1;  // p (always needed)
    if (SHMOD_ != 0.0) count += 1;  // t (thermal)
    else count += 0;  // t aliases to e
    if (RDSMOD_ != 0.0) count += 2;  // di, si
    if (RGATEMOD_ != 0.0) count += 2;  // gi, gm
    if (RBODYMOD_ != 0.0) count += 3;  // b, sb, db (internal body)
    else count += 1;  // b only (sb/db alias to b)
    count += 2;  // branch nodes _br1_7, _br2_8
    return count;
}

void BsimsoiGenModel::allocateInternalNodes(NodeId& internalNodeBase) {
    // 动态分配：折叠的节点别名到外部节点
    // p (substrate contact) - always allocated
    nodes_[4] = internalNodeBase++;  // p

    // b (internal body)
    if (RBODYMOD_ != 0.0) {
        nodes_[5] = internalNodeBase++;  // b
    } else {
        nodes_[5] = nodes_[3];  // alias to e (external body)
    }

    // t (thermal node)
    // If user provided a 5th external node (thermal port), use it directly
    // Otherwise allocate internally or alias to e (no self-heating)
    if (externalThermalNode_ != 0) {
        nodes_[6] = externalThermalNode_;  // use external thermal node
    } else if (SHMOD_ != 0.0 && RTH0_ != 0.0) {
        nodes_[6] = internalNodeBase++;  // t (active thermal, internal)
    } else {
        nodes_[6] = nodes_[3];  // alias to e (no self-heating)
    }

    // di (internal drain)
    if (RDSMOD_ != 0.0) {
        nodes_[7] = internalNodeBase++;
    } else {
        nodes_[7] = nodes_[1];  // alias to d
    }

    // si (internal source)
    if (RDSMOD_ != 0.0) {
        nodes_[8] = internalNodeBase++;
    } else {
        nodes_[8] = nodes_[2];  // alias to s
    }

    // gi (internal gate)
    if (RGATEMOD_ != 0.0) {
        nodes_[9] = internalNodeBase++;
    } else {
        nodes_[9] = nodes_[0];  // alias to g
    }

    // gm (gate mid)
    if (RGATEMOD_ != 0.0) {
        nodes_[10] = internalNodeBase++;
    } else {
        nodes_[10] = nodes_[0];  // alias to g
    }

    // sb, db (source/drain body contacts)
    if (RBODYMOD_ != 0.0) {
        nodes_[11] = internalNodeBase++;  // sb
        nodes_[12] = internalNodeBase++;  // db
    } else {
        nodes_[11] = nodes_[5];  // alias to b
        nodes_[12] = nodes_[5];  // alias to b
    }

    // branch nodes (always allocated)
    nodes_[13] = internalNodeBase++;  // _br1_7
    nodes_[14] = internalNodeBase++;  // _br2_8
}

